class Solution {
public:
    vector<int> countSteppingNumbers(int low, int high) {
        vector<int> answer;
        if (low == 0) {
            answer.push_back(0);
        }
        queue<long long> q;
        for (int digit = 1; digit <= 9; ++digit) {
            q.push(digit);
        }
        while (!q.empty()) {
            long long value = q.front();
            q.pop();
            if (value > high) {
                continue;
            }
            if (value >= low) {
                answer.push_back(static_cast<int>(value));
            }
            int digit = value % 10;
            if (digit > 0) {
                q.push(value * 10 + digit - 1);
            }
            if (digit < 9) {
                q.push(value * 10 + digit + 1);
            }
        }
        sort(answer.begin(), answer.end());
        return answer;
    }
};
